import { GetServerSideProps, InferGetServerSidePropsType } from 'next';
import Head from 'next/head';
import PostSummaryCard from '@/src/components/PostSummaryCard';
import { getPostSummaries } from '../../backend/services/cms';
import type { BlogPostSummary } from '../../backend/services/cms';
import MainLayout from '@/src/components/layout/MainLayout';

export const getServerSideProps: GetServerSideProps<{
  posts: BlogPostSummary[];
}> = async (context) => {
  const posts = await getPostSummaries();

  return {
    props: {
      posts,
    },
  };
};

export default function BlogIndexPage({ posts }: InferGetServerSidePropsType<typeof getServerSideProps>) {
  return (
    <MainLayout
      title="Latest Insights | CABI"
      description="Discover the latest news, updates, and stories from the CABI team."
    >
      <div className="bg-slate-50 dark:bg-slate-900">
        {/* Hero Section */}
        <div className="relative bg-indigo-900 overflow-hidden">
          <div className="absolute inset-0">
            <div className="absolute inset-0 bg-gradient-to-r from-indigo-800 to-purple-800 mix-blend-multiply" />
            <div className="absolute bottom-0 left-0 right-0 h-20 bg-gradient-to-t from-slate-50 dark:from-slate-900 to-transparent" />
          </div>
          <div className="relative max-w-7xl mx-auto py-24 px-4 sm:py-32 sm:px-6 lg:px-8 flex flex-col items-center text-center">
            <h1 className="text-4xl font-extrabold tracking-tight text-white sm:text-5xl lg:text-6xl mb-6 drop-shadow-sm">
              CABI Insights
            </h1>
            <p className="mt-2 text-xl text-indigo-100 max-w-2xl mx-auto">
              Exploring the future of transportation, technology, and sustainable agriculture.
            </p>
          </div>
        </div>

        {/* Content Section */}
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 -mt-20 relative z-10">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            {posts.map((post) => (
              <PostSummaryCard key={post.id} post={post} />
            ))}
          </div>
        </div>
      </div>
    </MainLayout>
  );
}